import { readFile, unlink } from 'node:fs/promises';
import { join } from 'node:path';

/*** Removes the superseded workflow only if it was generated by Paradox. */
export async function removeParadoxCollaboratorsWorkflowAsync(packageRoot: string): Promise<void> {
  const path = join(packageRoot, '.github', 'workflows', 'collaborators.yml');
  try {
    const existing = await readFile(path, 'utf8');
    if (existing.split(/\r?\n/, 1)[0] === '# Generated by Paradox. Do not edit manually.') {
      await unlink(path);
    }
  } catch (error: unknown) {
    if (error instanceof Error && 'code' in error && error.code === 'ENOENT') return;
    throw error;
  }
}
